<template><div ref="wrapper" class="surface-view surface-gpu"><canvas ref="canvas" class="surface-canvas" aria-label="3D surface preview"/><svg v-if="draft?.length||draftHoles?.length||handles?.length||cuts?.length||anchor||labels?.length||brushPath" class="surface-overlay" viewBox="-360 -270 720 540" aria-hidden="true" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none">
