 const started=performance.now(),c=canvas.value,rect=canvasViewport(c),ratio=Math.min(devicePixelRatio,2),scale=Math.min(rect.width/720,rect.height/540),width=Math.max(1,Math.round(rect.width*ratio)),height=Math.max(1,Math.round(rect.height*ratio));if(c.width!==width)c.width=width;if(c.height!==height)c.height=height;gl.viewport(0,0,width,height);gl.clearColor(...canvasTheme(c).rgb,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT|gl.STENCIL_BUFFER_BIT);gl.useProgram(program);const camera=props.camera,cy=Math.cos(camera.yaw),sy=Math.sin(camera.yaw),cp=Math.cos(camera.pitch),sp=Math.sin(camera.pitch),location=(name:string)=>gl!.getUniformLocation(program!,name);
